<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rechnungstool</title>
<style>
body{font-family:system-ui,Segoe UI,Arial,sans-serif;background:#f3f6fa;margin:0;color:#172033}.page{max-width:1700px;margin:auto;padding:26px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.top h1{margin:0;font-size:26px}.subtitle{color:#667085;margin-top:4px}.toolbar{display:grid;grid-template-columns:repeat(7,minmax(120px,1fr));gap:12px;background:#fff;border:1px solid #e1e6ef;border-radius:14px;padding:16px;box-shadow:0 4px 16px #1f29370b}.field{display:flex;flex-direction:column;gap:5px;font-size:12px;color:#667085}.field input,.field select{font:inherit;padding:9px 10px;border:1px solid #ccd3df;border-radius:8px;background:#fff;color:#172033}.toolbar .actions{display:flex;align-items:end}.primary{width:100%;padding:10px 14px;border:0;border-radius:8px;background:#1f4f8a;color:#fff;font-weight:650;cursor:pointer}.notice{margin:14px 0;padding:10px 12px;border-radius:9px;background:#eef5ff;color:#27415f;border:1px solid #d5e6ff}.workspace{display:grid;grid-template-columns:minmax(650px,1.25fr) minmax(450px,.75fr);gap:16px;margin-top:16px;align-items:start}.card{background:#fff;border:1px solid #e1e6ef;border-radius:14px;box-shadow:0 4px 16px #1f293708;overflow:hidden}.card-head{display:flex;justify-content:space-between;align-items:center;padding:14px 16px;border-bottom:1px solid #edf0f5}.card-head h2{margin:0;font-size:17px}.badge{background:#eef2f7;border-radius:999px;padding:4px 9px;font-size:12px;color:#526071}.list{max-height:68vh;overflow:auto}.order{display:grid;grid-template-columns:90px 1fr 110px;gap:10px;padding:12px 14px;border-bottom:1px solid #edf0f5;text-decoration:none;color:inherit}.order:hover{background:#f7faff}.order.selected{background:#eef5ff}.orderno{font-weight:700}.name{font-weight:650}.desc{font-size:13px;color:#667085;margin-top:3px}.date{text-align:right;font-size:12px;color:#667085}.detail{padding:16px}.detail h2{margin:0 0 6px}.detail .muted{color:#667085}.position{padding:12px 0;border-top:1px solid #edf0f5}.position:first-of-type{border-top:0}.pos-title{font-weight:650}.metrics{display:flex;gap:14px;flex-wrap:wrap;margin-top:6px;font-size:12px;color:#667085}.warning{background:#fff5db;border:1px solid #efd48b;border-radius:8px;padding:9px;margin:10px 0}.calc-row{padding:12px 0;border-top:1px solid #edf0f5}.calc-row:first-child{border-top:0}.status{display:inline-block;border-radius:999px;padding:3px 8px;font-size:11px;font-weight:700}.status.billable{background:#e8f7ee;color:#176b3a}.status.already_calculated{background:#eef2f7;color:#526071}.status.conflict{background:#fff0ee;color:#b42318}.status.not_due,.status.unsupported,.status.frozen{background:#fff5db;color:#8a6116}.calc-grid{display:grid;grid-template-columns:repeat(4,minmax(90px,1fr));gap:8px;margin-top:9px;font-size:12px}.calc-grid div{background:#f8fafc;border-radius:7px;padding:7px}.calc-grid strong{display:block;font-size:11px;color:#667085;margin-bottom:2px}.totals{margin-top:16px;border-top:1px solid #e1e6ef;padding-top:12px;display:grid;gap:5px}.total-line{display:flex;justify-content:space-between}.total-line.grand{font-size:18px;font-weight:800}.empty{padding:40px 20px;text-align:center;color:#667085}.back{color:#475467;text-decoration:none}@media(max-width:1100px){.toolbar{grid-template-columns:repeat(2,1fr)}.workspace{grid-template-columns:1fr}.list{max-height:none}}
</style></head><body><div class="page"><div class="top"><div><h1>Rechnungstool</h1><div class="subtitle">Vorschau und Testlauf · angemeldet als {{ $adUsername ?: 'unbekannt' }}</div></div><a class="back" href="{{ route('dashboard') }}">← Hauptmenü</a></div>
