<div class="workspace"><section class="card"><div class="card-head"><h2>Aufträge</h2><span class="badge">{{ $auftraege->count() }} Treffer</span></div><div class="list">@forelse($auftraege as $a)<a class="order {{ $selected&&(int)$selected->intAufNr===(int)$a->intAufNr?'selected':'' }}" href="{{ route('fakturierung.index',array_filter(['von'=>$von,'bis'=>$bis,'art'=>$art,'q'=>$q,'auftragsnr'=>$auftragsnr?:null,'kundennr'=>$kundennr?:null,'accountings'=>$accountings?'1':null,'auftrag'=>$a->intAufNr])) }}"><div class="orderno">#{{ $a->intAufNr }}</div><div><div class="name">{{ $kunden->get($a->intKID)?->strName??('Kunde '.$a->intKID) }}</div><div class="desc">{{ $a->strBeschreibung }}</div></div><div class="date">{{ $a->letztesRechnungsdatum?'zuletzt '.\Carbon\Carbon::parse($a->letztesRechnungsdatum)->format('d.m.Y'):'noch keine Rechnung' }}</div></a>@empty<div class="empty">Keine Aufträge gefunden.</div>@endforelse</div></section>
<section class="card">@if($selected)
<div class="card-head"><div><h2>Auftrag #{{ $selected->intAufNr }}</h2><div class="subtitle">{{ $kunden->get($selected->intKID)?->strName??('Kunde '.$selected->intKID) }}</div></div></div>
<div class="detail"><p><strong>{{ $selected->strBeschreibung }}</strong></p>
